CREATE TABLE `resource_grants` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`resource_type` VARCHAR(40) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`grantee_membership_id` CHAR(36) CHARACTER SET ascii NOT NULL,`grantor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`reason` VARCHAR(500) NOT NULL,`status` ENUM('active','revoked') NOT NULL DEFAULT 'active',`expires_at` DATETIME(3) NOT NULL,`revoked_at` DATETIME(3) NULL,`revoked_by` CHAR(36) CHARACTER SET ascii NULL,`revocation_reason` VARCHAR(500) NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_resource_grants_grantee`(`organization_id`,`grantee_membership_id`,`status`,`expires_at`),KEY `idx_resource_grants_resource`(`organization_id`,`workspace_id`,`resource_type`,`resource_id`,`status`,`expires_at`),KEY `idx_resource_grants_created`(`organization_id`,`created_at`,`id`),CONSTRAINT `fk_resource_grants_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_workspace` FOREIGN KEY(`workspace_id`) REFERENCES `workspaces`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_grantee` FOREIGN KEY(`grantee_membership_id`) REFERENCES `memberships`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_grantor` FOREIGN KEY(`grantor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grants_revoker` FOREIGN KEY(`revoked_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `resource_grant_actions` (`grant_id` CHAR(36) CHARACTER SET ascii NOT NULL,`capability_code` VARCHAR(80) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`grant_id`,`capability_code`),KEY `idx_resource_grant_actions_capability`(`capability_code`,`grant_id`),CONSTRAINT `fk_resource_grant_actions_grant` FOREIGN KEY(`grant_id`) REFERENCES `resource_grants`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_resource_grant_actions_capability` FOREIGN KEY(`capability_code`) REFERENCES `capabilities`(`code`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `resource_grant_audit_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`grant_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` ENUM('created','extended','revoked','expired','accessed','access_denied') NOT NULL,`resource_type` VARCHAR(40) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`capability` VARCHAR(80) CHARACTER SET ascii NULL,`surface` ENUM('api','worker','export','file','event','sse') NULL,`outcome` ENUM('allowed','denied') NOT NULL,`reason` VARCHAR(500) NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`schema_version` SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(`id`),KEY `idx_resource_grant_audit_grant`(`grant_id`,`occurred_at`),KEY `idx_resource_grant_audit_org`(`organization_id`,`occurred_at`),KEY `idx_resource_grant_audit_trace`(`trace_id`),CONSTRAINT `fk_resource_grant_audit_grant` FOREIGN KEY(`grant_id`) REFERENCES `resource_grants`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grant_audit_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `resource_grant_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`operation` VARCHAR(80) CHARACTER SET ascii NOT NULL,`idempotency_key_hash` CHAR(64) CHARACTER SET ascii NOT NULL,`request_hash` CHAR(64) CHARACTER SET ascii NOT NULL,`grant_id` CHAR(36) CHARACTER SET ascii NOT NULL,`grant_version` INT UNSIGNED NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_resource_grant_operation`(`actor_id`,`operation`,`idempotency_key_hash`),KEY `idx_resource_grant_operations_org`(`organization_id`,`created_at`),CONSTRAINT `fk_resource_grant_operations_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grant_operations_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_resource_grant_operations_grant` FOREIGN KEY(`grant_id`) REFERENCES `resource_grants`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
